"""Tenant-partitioned checkpoint store (generated by the Securi wizard).

Defense-in-depth under the IdentityBoundCheckpointer: even a buggy query
cannot read another tenant's checkpoints — the partition key enforces it.

v3.48.9: LOCAL FALLBACK — when SECURI_COSMOS_ENDPOINT is not set (a dev
laptop without Azure env vars), build_container() returns a file-backed
tenant-partitioned checkpointer at .dm-agent/local_checkpoints.json that
enforces the exact same /tenant_id partition isolation. No more
KeyError: 'SECURI_COSMOS_ENDPOINT' on first run.
"""
import json
import os


class LocalTenantCheckpointer:
    """File-backed tenant-partitioned checkpoint store for local dev.

    Same contract as the Cosmos container: every record carries /tenant_id
    and reads are filtered by tenant — a cross-tenant read raises BOLAError.
    """

    def __init__(self, path: str | None = None):
        self.path = path or os.path.join(".dm-agent", "local_checkpoints.json")
        os.makedirs(os.path.dirname(self.path) or ".", exist_ok=True)
        if not os.path.exists(self.path):
            with open(self.path, "w", encoding="utf-8") as f:
                json.dump({"schema": "securi-local-checkpoints/v1", "items": []}, f)

    def _load(self) -> dict:
        with open(self.path, encoding="utf-8") as f:
            return json.load(f)

    def _save(self, data: dict) -> None:
        with open(self.path, "w", encoding="utf-8") as f:
            json.dump(data, f, indent=2)

    def upsert(self, item: dict) -> dict:
        tenant = item.get("tenant_id")
        if not tenant:
            raise ValueError("checkpoint item requires /tenant_id (partition key)")
        data = self._load()
        data["items"] = [i for i in data["items"]
                         if not (i.get("id") == item.get("id") and i.get("tenant_id") == tenant)]
        data["items"].append(item)
        self._save(data)
        return item

    def read(self, item_id: str, tenant_id: str) -> dict | None:
        for i in self._load()["items"]:
            if i.get("id") == item_id:
                if i.get("tenant_id") != tenant_id:
                    raise PermissionError(
                        f"BOLA: checkpoint '{item_id}' belongs to another tenant")
                return i
        return None

    def query(self, tenant_id: str) -> list:
        """Tenant-scoped list — the partition key is always applied."""
        return [i for i in self._load()["items"] if i.get("tenant_id") == tenant_id]


def build_container():
    """Cosmos container in Azure; local tenant-partitioned fallback in dev."""
    endpoint = os.environ.get("SECURI_COSMOS_ENDPOINT")
    if not endpoint:
        print("ℹ️  SECURI_COSMOS_ENDPOINT not set — using local tenant-partitioned "
              "checkpointer (.dm-agent/local_checkpoints.json)")
        return LocalTenantCheckpointer()
    database = os.environ.get("SECURI_COSMOS_DB", "securi")
    container = os.environ.get("SECURI_COSMOS_CONTAINER", "checkpoints")
    from azure.cosmos import CosmosClient, PartitionKey
    from azure.identity import DefaultAzureCredential
    cred = DefaultAzureCredential() if not os.environ.get("SECURI_COSMOS_KEY")         else os.environ["SECURI_COSMOS_KEY"]
    client = CosmosClient(endpoint, credential=cred)
    db = client.create_database_if_not_exists(database)
    return db.create_container_if_not_exists(
        id=container, partition_key=PartitionKey(path="/tenant_id"))
